/** Validates `input` against the registered `inputSchema` before the executor runs; a schema rejection is returned as a `ToolResponse` and only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }
  const validateInput =
    tool.validateInput ?? this.validatorFor(name, this.resolveDefinition(tool.definitionSource).inputSchema);
  if (!validateInput(input)) {
    const rejection = describeSchemaErrors(validateInput.errors ?? []);
    log.warn('tool', 'input rejected by inputSchema', {name, reasons: rejection});
    return {result: `Invalid tool input: ${rejection}`};
